WITH base AS (SELECT *, SUBSTRING(product_name, 1, 2) AS product_name_prefix, COALESCE(brand, 'DIRECT') AS brand_clean FROM products WHERE stock_qty != 393), latest AS (SELECT id, product_name, brand, price, stock_qty, supplier_id, product_name_prefix FROM base QUALIFY ROW_NUMBER() OVER (PARTITION BY brand, supplier_id ORDER BY stock_qty DESC NULLS LAST, id) = 1), kept_keys AS (SELECT id, supplier_id FROM latest INTERSECT SELECT id, supplier_id FROM products WHERE brand IS NULL), verified AS (SELECT s.* FROM latest s JOIN kept_keys k ON s.id = k.id AND s.supplier_id = k.supplier_id), eligible AS (SELECT s.* FROM verified s WHERE EXISTS (SELECT 1 FROM inventory x WHERE x.product_id = s.id AND x.last_restock < '2024-02-01')), enriched AS (SELECT e.*, b.city FROM eligible e JOIN suppliers b ON e.supplier_id = b.id) SELECT s.product_name, s.brand, s.price, s.stock_qty, s.supplier_id, s.product_name_prefix, (SELECT MAX(t2.cost) FROM products t2 WHERE t2.supplier_id = s.supplier_id) AS max_product_cost FROM enriched s ORDER BY price DESC, brand DESC;
